-- composition of rule kernels partitioned_execution x redundant_order_keys (duckdb), template product
SELECT count(*) FROM (SELECT DISTINCT 10::bigint AS c0, a1.c0 AS c1 FROM tl AS a1) AS ka CROSS JOIN (SELECT (-1)::bigint AS c0, ({ 'a' : ((MAX ('2024-02-29'::date) OVER (PARTITION BY '{"k": 2, "a": [0]}'::jsonb) + 1) - '2024-01-01'::date), 'b' : '%'::text }).a AS c1 FROM (t4 POSITIONAL JOIN t1)) AS kb;
